: [{"id": "blk_mwktgo0411hcpe2", "type": "nav", "props": {"right": "", "title": "报名成功", "showBack": true}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwktgo04123nopo", "type": "heading", "props": {"sub": "", "size": "lg", "text": "收到啦"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwktgo041368o4a", "type": "text", "props": {"size": "md", "text": "活动前一天会给你发提醒。当天到了直接找摊位就行，不用签到打卡，也不用自我介绍。想提前走随时可以走。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwktgo0414d6nd4", "type": "qrcode", "props": {"url": "", "size": 132, "label": "扫码查看活动详情"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwktgo04189bsf9", "type": "infoCard", "props": {"items": [{"id": "it_mwktgo0415q8m41", "icon": "contact", "label": "校心理健康教育中心", "value": "学生活动中心 3 楼 302，工作日 14:00–17:00 可预约"}, {"id": "it_mwktgo04168ceye", "icon": "contact", "label": "全国心理援助热线", "value": "12356"}, {"id": "it_mwktgo04173cvc0", "icon": "contact", "label": "紧急情况", "value": "110 / 120"}], "title": "如果现在不太好受"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}], "theme": {"bg": "#faf8f5", "font": "sans", "text": "#1f3129", "accent": "#b88c72", "radius": 16, "primary": "#2d5046", "spacing": 1, "fontScale": 1, "buttonStyle": "gradient"}, "title": "考试周心晴游园会", "createdAt": 1794927454851, "published": {"at": 1794956367000, "url": "http://localhost:5173/p/pz9lps", "slug": "pz9lps"}, "updatedAt": 1794927565010}' AS JSON), 'manual', '00000000-0000-4000-8000-000000000001'
  FROM projects p WHERE p.public_slug = 'campus-fair'
