VALUES
  ('a1000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000001', NULL, '心理知识问答', '5 道题，约 2 分钟，匿名作答，不评分也不诊断。', '心理科普', 'optional',
   'photo', 'QUIZ / 05', '了解自己，是照顾好自己的一部分', 'published', CAST('{"id": "doc_mwkvxkme9m1hy41", "meta": {"org": "心屿心理协会 × 心理健康教育中心", "place": "线上答题，无需到场", "contact": "公众号「心屿」后台留言", "startAt": "2026-11-18T09:00:00", "capacity": 0, "deadline": "2026-11-30T23:59:00", "activityType": "心理科普"}, "slug": "p30b9u", "pages": [{"bg": "", "id": "pg-f808e760-7ae4-45e6-8de0-4b695a481e9b", "name": "首页", "role": "home", "blocks": [{"id": "blk-9308ad75-de52-4c6f-8108-f9d656bbebd7", "type": "nav", "props": {"title": "心理知识问答"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-065380de-ec2b-4cba-98ee-cb943444adff", "type": "banner", "props": {"title": "了解自己，是照顾好自己的一部分", "subtitle": "5 道题 · 约 2 分钟 · 匿名作答"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-f05839ef-973d-4569-a91b-8bf762515e64", "type": "infoCard", "props": {"text": "本问卷仅用于心理健康科普及自我察觉，不是诊断工具", "title": "活动信息", "items": [{"id": "it-wellbeing-quiz-0", "icon": "time", "label": "题量", "value": "5 题"}, {"id": "it-wellbeing-quiz-1", "icon": "time", "label": "时长", "value": "约 2 分钟"}, {"id": "it-wellbeing-quiz-2", "icon": "org", "label": "方式", "value": "匿名作答，不上传服务器"}, {"id": "it-wellbeing-quiz-3", "icon": "contact", "label": "结果", "value": "只给你自己看"}]}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-note-wellbeing-quiz", "type": "text", "props": {"text": "这是一份轻量的心理健康小测，不是诊断，也不打分。答完之后你会看到几段说明，帮你辨认最近的状态。所有答案只在你的浏览器里计算，不会上传服务器，也没有人能看到。", "align": "left"}, "style": {}, "hidden": false}, {"id": "blk-5d8536e8-65d3-4f65-a86f-521c148c3dac", "type": "countdown", "props": {"title": "距活动结束", "endsAt": "2026-12-31T23:59:59", "label": "本期开放至", "target": "2026-11-30T23:59:00"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-e8b5b419-06f3-4e57-a8e6-a34540184efd", "type": "button", "props": {"text": "开始答题"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-ad48f971-4b93-4c04-975b-e8853a1ef256", "name": "科普", "role": "content", "blocks": [{"id": "blk-e0ca6474-fa0c-4bea-aa7c-a448fe03f281", "type": "heading", "props": {"text": "开始之前"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-a1e5cd4e-bb70-4e48-9edf-606230721ab2", "type": "text", "props": {"text": "心理困扰不是「想太多」，也不是意志力问题。它和感冒发烧一样，是可被理解和处理的状态。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-49b59f17-b563-47a3-bc9d-de5122cf049c", "type": "divider", "props": {}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-8bdfbc00-b011-4a6b-bffe-fb6cb8d50a21", "type": "text", "props": {"text": "如果你连续两周情绪低落、睡眠或食欲明显改变，建议到心理中心聊一聊。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-a09ec229-4539-4b1d-bc46-48f76de38d6e", "type": "text", "props": {"text": "紧急情况可拨打学校心理援助热线，或直接前往心理中心。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-844715a7-debd-46af-81aa-ddec6817a7dd", "name": "答题", "role": "form", "blocks": [{"id": "blk-8d404e09-f773-476a-9eac-9b1d1f661daa", "type": "heading", "props": {"text": "答题"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-8c3308a9-760d-4d4e-8404-48bee0b9ac50", "type": "form", "props": {"fields": [{"id": "q1", "type": "radio", "label": "长期睡眠不足最常见的影响是？", "options": [{"label": "注意力与情绪调节能力下降", "value": "a"}, {"label": "身高增加", "value": "b"}, {"label": "没有影响", "value": "c"}], "required": true}, {"id": "q2", "type": "radio", "label": "朋友向你倾诉低落情绪时，比较合适的回应是？", "options": [{"label": "先听，再问对方需要什么", "value": "a"}, {"label": "立刻给出解决方案", "value": "b"}, {"label": "说「这没什么大不了的」", "value": "c"}], "required": true}, {"id": "q3", "type": "checkbox", "label": "以下哪项属于自我关怀的做法？", "options": [{"label": "允许自己有做不到的事", "value": "a"}, {"label": "保持规律作息", "value": "b"}, {"label": "把自己的情绪全部压下去", "value": "c"}], "required": false}, {"id": "note", "type": "textarea", "label": "想对自己说的一句话（可选）", "required": false}], "submitText": "提交答案"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-f0dc5b4f-cb5d-452d-8622-b484471b075e", "name": "完成", "role": "success", "blocks": [{"id": "blk-3d148455-9ec4-4297-bbe5-49f7f0b68728", "type": "heading", "props": {"text": "谢谢你认真作答"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-2b581dcd-8501-4657-87f8-2d37100fda3a", "type": "text", "props": {"text": "心理知识只是起点，真正的照顾发生在每一天的小事里。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-095c5c86-901e-4dec-bfc8-180cc26183a4", "type": "text", "props": {"text": "想聊聊的话，小程序「心屿」首页有免费的自助工具与预约入口。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}], "theme": {"bg": "#FAF7FF", "font": "sans", "text": "#231F3D", "accent": "#C4B5E8", "radius": 18, "primary": "#7C6BA8", "spacing": 1.1, "fontScale": 1, "buttonStyle": "solid"}, "title": "心理知识问答", "createdAt": 1794931602854, "published": {"at": 1794960415000, "url": "http://localhost:5173/p/p30b9u", "slug": "p30b9u"}, "updatedAt": 1794931602855}' AS JSON), 1,
   JSON_OBJECT(), 'wellbeing-quiz', 'b1000000-0000-4000-8000-000000000002')
