gn": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-1b53436e-5d0a-4b74-8eab-a932ef6aad71", "name": "科普", "role": "content", "blocks": [{"id": "blk-2f560e77-ed38-4343-8e0e-af1b7681c5c7", "type": "heading", "props": {"text": "开始之前"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-efe0fdd4-3c27-4e08-af79-4fb8ca33fd68", "type": "text", "props": {"text": "心理困扰不是「想太多」，也不是意志力问题。它和感冒发烧一样，是可被理解和处理的状态。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-4e34c690-82d3-47f1-90f5-5dd2ed2e3bc8", "type": "divider", "props": {}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-4a4e575e-4ba8-45de-9c73-4ea636393798", "type": "text", "props": {"text": "如果你连续两周情绪低落、睡眠或食欲明显改变，建议到心理中心聊一聊。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-68d44c0a-c431-4d59-8f42-4d6ea28aaf64", "type": "text", "props": {"text": "紧急情况可拨打学校心理援助热线，或直接前往心理中心。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkvon1i3o22x9c", "type": "image", "props": {"url": "", "ratio": "4:3", "caption": ""}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-64762163-3fc8-4c90-b1d4-0bc2c8b741da", "name": "答题", "role": "form", "blocks": [{"id": "blk-f20d9ec1-a06d-495f-89b7-a11ffa8ab64e", "type": "heading", "props": {"text": "答题"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-2a0f416c-15f4-456e-9cf1-a11195ac6d7a", "type": "form", "props": {"fields": [{"id": "q1", "type": "radio", "label": "长期睡眠不足最常见的影响是？", "options": [{"label": "注意力与情绪调节能力下降", "value": "a"}, {"label": "身高增加", "value": "b"}, {"label": "没有影响", "value": "c"}], "required": true}, {"id": "q2", "type": "radio", "label": "朋友向你倾诉低落情绪时，比较合适的回应是？", "options": [{"label": "先听，再问对方需要什么", "value": "a"}, {"label": "立刻给出解决方案", "value": "b"}, {"label": "说「这没什么大不了的」", "value": "c"}], "required": true}, {"id": "q3", "type": "checkbox", "label": "以下哪项属于自我关怀的做法？", "options": [{"label": "允许自己有做不到的事", "value": "a"}, {"label": "保持规律作息", "value": "b"}, {"label": "把自己的情绪全部压下去", "value": "c"}], "required": false}, {"id": "note", "type": "textarea", "label": "想对自己说的一句话（可选）", "required": false}], "submitText": "提交答案"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "pg-c0c400a9-f5d2-4f3b-a48e-908d8a3cec8b", "name": "完成", "role": "success", "blocks": [{"id": "blk-c4517d96-b406-430c-a463-fa18888cbb00", "type": "heading", "props": {"text": "谢谢你认真作答"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-9541860c-e5d8-4ec6-b5d2-53a99d8b7243", "type": "text", "props": {"text": "心理知识只是起点，真正的照顾发生在每一天的小事里。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk-09a8a4be-a724-430d-bb9f-d06dc869c8cb", "type": "text", "props": {"text": "想聊聊的话，小程序「心屿」首页有免费的自助工具与预约入口。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}], "theme": {"bg": "#FAF7FF", "font": "sans", "text": "#231F3D", "accent": "#C4B5E8", "radius": 18, "primary": "#7C6BA8", "spacing": 1.1, "fontScale": 1, "buttonStyle": "solid"}, "title": "情绪小测 · 你最近还好吗", "createdAt": 1794931106912, "published": null, "updatedAt": 1794933739432}' AS JSON), 'manual', '00000000-0000-4000-8000-000000000001'
  FROM projects p WHERE p.public_slug = 'mind-education'
ON DUPLICATE KEY UPDATE document = VALUES(document);

