   'photo', 'GROUP / 12', '坐下来，聊一聊这一周', 'published', CAST('{"id": "doc_mwkbusfh8mac2ui", "meta": {"org": "心理健康教育中心 · 朋辈支持小组", "place": "西区团辅室 B203", "contact": "报名后由带领者私信联系", "startAt": "2026-11-23T19:00:00", "capacity": 12, "deadline": "2026-11-22T20:00:00", "activityType": "心理活动"}, "slug": "p8ld31", "pages": [{"bg": "", "id": "page_mwkbusfh7oh3s3k", "name": "首页", "role": "home", "blocks": [{"id": "blk-nav-peer-support", "type": "nav", "props": {"title": "校园心理互助小组", "showBack": true, "right": ""}, "style": {}, "hidden": false}, {"id": "blk-banner-peer-support", "type": "banner", "props": {"title": "坐下来，聊一聊这一周", "subtitle": "12 人小组 · 90 分钟 · 全程匿名", "image": "", "full": true}, "style": {}, "hidden": false}, {"id": "blk-info-peer-support", "type": "infoCard", "props": {"title": "活动信息", "items": [{"id": "it-peer-support-0", "icon": "time", "label": "时间", "value": "11 月 23 日 19:00–20:30"}, {"id": "it-peer-support-1", "icon": "place", "label": "地点", "value": "西区团辅室 B203"}, {"id": "it-peer-support-2", "icon": "org", "label": "主办", "value": "心理健康教育中心 · 朋辈支持小组"}, {"id": "it-peer-support-3", "icon": "contact", "label": "人数", "value": "每场 12 人，需提前报名"}]}, "style": {}, "hidden": false}, {"id": "blk-note-peer-support", "type": "text", "props": {"text": "这里不是心理咨询，也不做任何记录。它只是一群同学坐在一起，说说这周过得怎么样。愿意开口就开口，愿意听就听。", "align": "left"}, "style": {}, "hidden": false}, {"id": "blk-cd-peer-support", "type": "countdown", "props": {"label": "距本期开始", "target": "2026-11-23T19:00:00"}, "style": {}, "hidden": false}, {"id": "blk_mwkbwa9j9bffgad", "type": "form", "props": {"title": "报名信息", "fields": [{"id": "f_mwkbwa9j9c6d33p", "type": "text", "label": "姓名", "options": [], "required": true, "placeholder": "张博杨"}, {"id": "f_mwkbwa9j9d18nuo", "type": "tel", "label": "手机号", "options": [], "required": true, "placeholder": "用于接收活动通知"}, {"id": "f_mwkbwa9j9eidyuv", "type": "textarea", "label": "备注", "options": [], "required": false, "placeholder": "有什么想告诉我们的？"}], "buttonText": "提交报名", "successHint": "提交后我们会短信通知你"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbx4d3enea75k", "type": "qrcode", "props": {"url": "", "size": 132, "label": "扫码查看活动详情"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "page_mwkbusfh7y3cxok", "name": "这场怎么进行", "role": "content", "blocks": [{"id": "blk_mwkbusfh7pcbuus", "type": "nav", "props": {"right": "", "title": "这场怎么进行", "showBack": true}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7qambkw", "type": "heading", "props": {"sub": "", "size": "lg", "text": "大概是这样"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7rxc0do", "type": "text", "props": {"size": "md", "text": "先一起做个小热身，然后分成小组聊。全程自愿发言，不想说就听着。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7sccjki", "type": "divider", "props": {"label": ""}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7tf4yej", "type": "heading", "props": {"sub": "", "size": "lg", "text": "我们不做什么"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7un2hn7", "type": "text", "props": {"size": "md", "text": "这里不是心理咨询，也不做任何诊断。我们只是同学之间的互相陪伴。如果你需要专业帮助，页面底部有求助入口。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7v2uvd9", "type": "heading", "props": {"sub": "", "size": "lg", "text": "关于保密"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7w7ar0j", "type": "text", "props": {"size": "md", "text": "现场聊的内容不出这个房间。报名信息只有活动负责人能看到，活动结束就删。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh7xj4z6b", "type": "button", "props": {"full": true, "text": "我想参加", "action": {"url": "", "type": "page", "pageId": "page_20741a32", "targetRole": "form"}, "variant": "primary"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "page_mwkbusfh8940ecx", "name": "报名", "role": "form", "blocks": [{"id": "blk_mwkbusfh7z7h20t", "type": "nav", "props": {"right": "", "title": "报名", "showBack": true}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh803avis", "type": "heading", "props": {"sub": "", "size": "lg", "text": "填两行就好"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh81gj3k9", "type": "text", "props": {"size": "md", "text": "手机号只用来发活动通知，不会给第三方。想匿名参加的话，昵称随便写一个，手机号可以留空。"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh84cr02r", "type": "form", "props": {"title": "报名信息", "fields": [{"id": "f_mwkbusfh8298e1e", "type": "text", "label": "怎么称呼你", "options": [], "required": true, "placeholder": "真名或昵称都行"}, {"id": "f_mwkbusfh83cssnt", "type": "tel", "label": "手机号（选填）", "options": [], "required": false, "placeholder": "只用于发活动通知，可不填"}], "buttonText": "提交报名", "successHint": "提交后我们会通知你"}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}, {"id": "blk_mwkbusfh88swfwa", "type": "radio", "props": {"hint": "匿名参加的话，现场也不会点名", "options": ["用昵称，匿名参加", "用真名参加"], "question": "想以什么方式参加", "required": true}, "style": {"bg": "", "align": "left", "radius": 0, "paddingX": 20, "paddingY": 10}, "hidden": false}]}, {"bg": "", "id": "page_mwkbusfh8lefqo1", "name": "报名成功", "role": "success", "blocks": [{"id": "blk_mwkbusfh8ar0umx", "type": "nav", "props": {"right": "", "title": "报